appearances.css:
.app{padding:6px;font-size:10px}
.app button,.app input,.app select{padding:2px 5px;min-height:24px;font-size:10px;border-radius:3px}
h2{font-size:10px;letter-spacing:.5px;margin:0 0 4px}
.row,.toolbar,.bank,.orders{gap:4px}
.toolbar{margin:4px 0}
.panel{padding:6px;margin-top:5px;border-radius:4px}
.small{display:none}
.status{margin-top:2px;min-height:0;font-size:10px}
label{font-size:9px;gap:1px}
input[type=number]{width:56px}
input[type=text]{width:120px}
.bank button{min-width:80px}
.orders button{min-width:70px;font-size:9px}
.trackertable th{padding:4px 2px}
.trackertable td{height:22px}
.trackertable td.rowno{font-size:9px}
.trackertable button{min-height:22px!important;padding:2px!important;font-size:10px}
.trackertable{min-width:0}
.inspector{gap:4px;margin-top:4px}
.trackbox{padding:5px}
.footer{padding-top:5px}
